"use strict";
// cmd-utils.lib.civet

type AutoPromise<T> = Promise<Awaited<T>>;
import {LOG, DBG, ERR} from 'logger'
import {
	undef, defined, notdefined, getOptions, getErrStr, centered,
	} from 'base'
import {hash} from 'datatypes'
import {CTimer} from 'timer'
import {toRelPath} from 'llfs'
import {f} from 'llutils'
import {allFilesMatching, parsePath} from 'fsys'
import {doCompileCivet} from 'civet'
import {TTask, runTasks} from 'run-tasks'
import {doUnitTest} from 'compile'

// ---------------------------------------------------------------------------

export const cmdStep = (str: string): string => {

	return centered(str, {char: '=', color: 'cyan'})
}

// ---------------------------------------------------------------------------

type opt = {
	root: string
	force: boolean
	quiet: boolean
	verbose: boolean
	}

const getCmdOptions = (hOptions: hash = {}): opt => {

	return getOptions<opt>(hOptions, {
		root: Deno.cwd(),
		force: false,
		quiet: false,
		verbose: false
		})
}

// ---------------------------------------------------------------------------
// Exclude any files in a subdirectory of 'test' directory

const filter = (path: string): boolean => {

	const relPath = toRelPath(path)
	const index = relPath.indexOf('/test/')
	const keep = (index === -1)
	DBG(`${relPath} ${keep ? 'keep' : 'discard'}`)
	return (relPath.indexOf('/test/') === -1)
}

// ---------------------------------------------------------------------------

export const compileAllLibs = async (
		hOptions: hash = {}
		): AutoPromise<boolean> => {

	return await compileFilesMatching('**/*.lib.civet', {...hOptions, filter})
}

// ---------------------------------------------------------------------------

export const compileAllUnitTests = async (
		hOptions: hash = {}
		): AutoPromise<boolean> => {

	return await compileFilesMatching('**/*.test.civet', {...hOptions, filter})
}

// ---------------------------------------------------------------------------

export const compileAllCommands = async (
		hOptions: hash = {}
		): AutoPromise<boolean> => {

	return await compileFilesMatching('**/*.cmd.civet', {...hOptions, filter})
}

// ---------------------------------------------------------------------------

export type TCompileContext = {
	nCompiled: number
	nNotNeeded: number
	timeTaken: number
	}

export const compileFilesMatching = async (
		pat: string,
		hOptions: hash = {}
		): AutoPromise<boolean> => {

	const {root, force, quiet, verbose} = getCmdOptions(hOptions)
	try {
		LOG(cmdStep("COMPILE ALL LIBS"))
		const timer = new CTimer()
		const results=[];for (const path of allFilesMatching(pat, {root})) {
			results.push(({
				title: toRelPath(path),
				task: async (
						ctx: TCompileContext,
						task: TTask
						): AutoPromise<void> => {
					task.output = 'Compiling...'
					const hResult = await doCompileCivet.handleFile(path, {
						force,
						postproc: false
						})
					if (hResult.notNeeded) {
						ctx.nNotNeeded += 1
						task.title = ''
					}
					else {
						ctx.nCompiled += 1
						task.title = f`${task.title}:-14 ${'compiled'}:{green}`
					}
					return
				}
				}))
		};const lTasks =results
		const {
			nCompiled, nNotNeeded, timeTaken
			} = await runTasks(lTasks, {
				nCompiled: 0,
				nNotNeeded: 0,
				timeTaken: 0
				}, {concurrent: 8})

		if (nCompiled > 0) {
			LOG(`${nCompiled} libs compiled`)
		}
		if (nNotNeeded > 0) {
			LOG(`${nNotNeeded} libs already compiled`)
		}
		LOG(`   (${timeTaken} secs.)`)
		return true
	}
	catch (err) {
		ERR(`Not all libs compiled: ${getErrStr(err)}`)
		return false
	}
}

